import math
def r1(x): return math.floor(x*10+0.5)/10   # round-half-up to 1 dp (matches the page model)
# per-year [USSR/Russia, USA, China, Europe, Japan, India, Other]
M = {1965:[53,70,0,1,0,0,0], 2018:[10,27,28,6,5,4,0]}
for y in (1965, 2018):
    r = M[y]; tot = sum(r); duo = 100*(r[1]+r[0])/tot
    print(f'{y}: USA + USSR/Russia = {r1(duo)}% of {tot} launches')
